insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('sog-deina-mama-sii-soi-beim-naechstn-moi-weniga-lippnschdift-neema-mei-familiinschdrumpf-schaud-aus-wiara-reengboong', 'Sog deina Mama, sii soi beim nächstn Moi weniga Lippnschdift neema - mei Familiinschdrumpf schaud aus wiara Reengboong!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sag deiner Mama, sie soll beim nächsten Mal weniger Lippenstift nehmen - mein Familienstrumpf sieht aus wie ein Regenbogen!', '[{"kategorie": "wörtlich", "text": "\"Sag deiner Mama, sie soll beim nächsten Mal weniger Lippenstift nehmen - mein bestes Stück sieht aus wie ein Regenbogen!\"  2. Sag deiner Mutter, sie soll beim nächsten Mal weniger Lippenstift auftragen – mein kleiner Freund sieht aus wie ein Regenbogen nach dem Karneval!  3. Sag deiner Mutter, sie soll beim nächsten Mal weniger Lippenstift verwenden – mein Gerät sieht aus, als wär''s mit Wachsmalstiften verziert worden!"}]'::jsonb, ''),
  ('waunn-du-aupockst-fueued-sis-so-au-ois-daeaedn-zwa-loslossn', 'Waunn du aupockst, füüd sis so au, ois däädn zwa loslossn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn du anpackst, fühlt es sich an, als würden zwei loslassen!', '[{"kategorie": "wörtlich", "text": "\"Wenn du zupackst, wirkt das so, als hätten zwei losgelassen!\"  2. Du fasst hin, und man denkt, es hätten zwei losgelassen!  3. Mit dir am Werk fühlt sich’s an, als würden zwei loslassen und du gleich mit!"}]'::jsonb, ''),
  ('pockts-ma-in-buam-ned-z-hoat-au', 'Pockts ma in Buam ned z''hoat au!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Packt mir den Buben nicht zu hart an!', '[{"kategorie": "wörtlich", "text": "\"Packt mir den Jungen nicht zu hart an!\"  2. Geht bitte vorsichtig mit dem Jungen um!  3. Seid bitte nicht zu grob mit dem Jungen!"}]'::jsonb, ''),
  ('waun-i-des-foisch-aupock-bin-i-im-oasch-dahaam', 'Waun I des foisch aupock, bin I im Oasch dahaam!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn ich das falsch anpacke, bin ich im Arsch daheim!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich das falsch anpacke, bin ich im Arsch!\"  2. Wenn ich das nicht richtig angehe, bin ich erledigt!  3. Wenn ich da falsch loslege, bin ich geliefert!"}]'::jsonb, ''),
  ('di-brauch-i-wiara-lunganentzuendung', 'Di brauch I wiara Lunganentzündung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dich brauche ich wie eine Lungenentzündung!', '[{"kategorie": "wörtlich", "text": "\"Dich brauch ich wie ein Loch im Kopf!\"  2. Du bist so unnötig wie ein [[Schas]] im Wald!  3. Du bist ungefähr so hilfreich wie ein Regenschirm im Orkan!"}]'::jsonb, ''),
  ('fette-funsn', 'Fette Funsn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Fette Funsen!', '[{"kategorie": "wörtlich", "text": "\"Du vollgefressenes, eingebildetes  Frauenzimmer!\"  2. Du aufgeblasene, selbstverliebte Kuh!  3. Du fresssüchtige, eingebildete Gans!"}]'::jsonb, ''),
  ('tropfads-rossfut-dreckigs', 'Tropfads Rossfut, dreckigs!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Tropfendes Rossfut, dreckiges!', '[{"kategorie": "wörftlich", "text": "\"Tropfende Rossvotze, dreckige!\"  2. Du triefende, dreckige Schleimschleuder!  3. Du widerliche, sabbernde Rosshure!"}]'::jsonb, ''),
  ('brood-kaunn-schimmaen-und-wos-kaunnst-du', 'Brood kaunn schimmän, und wos kaunnst du?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Brot kann schimmeln, und was kannst du?', '[{"kategorie": "wörtlich", "text": "\"Selbst Brot hat mehr Potenzial als du - denn es kann wenigstens schimmeln!\"  2. Ein Stück Holz kann schwimmen – und du?  3. Ein Sack Reis kann umfallen – und was kannst du?"}]'::jsonb, ''),
  ('i-dadad-mi-jo-gean-geistig-mid-dia-duellian-owa-offnboa-bist-unbewoffnet', 'I dadad mi jo gean geistig mid dia duellian - owa offnboa bist unbewoffnet!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich täte mich ja gern geistig mit dir duellieren, aber offenbar bist du unbewaffnet!', '[{"kategorie": "wörtlich", "text": "2. Ich hätte Lust auf ein bisschen geistige Reibung gehabt, aber du bist offenbar rutschfest!  3. Ein geistiger Wettkampf wäre reizvoll – wenn du nicht intellektuell entwaffnet wärst!"}]'::jsonb, ''),
  ('du-schaasaugate-duempfaekrood', 'Du schaasaugate Dümpfäkrood!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du schasaugerte Dümpfelkrot!', '[{"kategorie": "wörtlich", "text": "\"Du sehbehinderte Tiefwasserkröte!\"  2. \"Du kurzsichtiger Sumpfbiber!\"  3. \"Du halbblinder Moorlurch!\""}]'::jsonb, ''),
  ('guad-schaust-aus-host-gschbiibm', 'Guad schaust aus - host gschbiibm?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Gut schaust du aus - hast du gespieben?', '[{"kategorie": "scherzhaft für", "text": "\"Gut siehst du aus - hast du gekotzt?\"  2. Siehst gut aus - hast du gerade erbrochen?  3. Siehst frisch und fit aus - hast dich gerade übergeben?"}]'::jsonb, ''),
  ('a-bueuedungslegastenika-is-da-intellektuelle-bruada-vom-duaftrottl', 'A Büüdungslegastenika is da intellektuelle Bruada vom Duaftrottl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Bildungslegastheniker ist der intellektuelle Bruder vom Dorftrottel!', '[{"kategorie": "wörtlich", "text": "\"Ein Bildungslegastheniker ist der intellektuelle Cousin des Dorftrottels!\"  2. Ein Bildungslegastheniker ist ein geistiger Blindgänger mit Lebenslauf!  3. Ein Bildungslegastheniker ist ein Dorftrottel mit Fachhochschulabschluss!"}]'::jsonb, ''),
  ('soewa-muass-da-gfoin', 'Söwa muass da gfoin!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Selber muss es dir gefallen!', '[{"kategorie": "wörtlich", "text": "\"Solange es dir selber gefällt!\"  2. Na, Hauptsache du selbst bist zufrieden damit!  3. Wenn’s dir taugt, ist ja alles gut!"}]'::jsonb, ''),
  ('friara-woara-maratonleifa-heid-is-a-zimmabrunnanbrunza-rennd-in-ana-tua-aufs-heisl', 'Friara woara Maratonleifa, heid is a Zimmabrunnanbrunza - rennd in ana Tua aufs Heisl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Früher war er Marathonläufer, heute ist er Zimmerbrunnenbrunzer – rennt in einer Tour aufs Häusel!', '[{"kategorie": "wörtlich", "text": "\"Früher war er Marathonläufer, heute ist er Klo-Sprinter – rennt in einer Tour aufs Häusel!\"  2. Früher lief er Langstrecke, heute sprintet er nur noch die Kurzstrecke zum Stillen Örtchen!  3. Ausdauersport war gestern – heute ist Dauerpinkeln sein Marathon!"}]'::jsonb, ''),
  ('du-moeoeladpappade-schaastrommae', 'Du mööladpappade Schaastrommä!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du mehlert-papperte Schastrommel!', '[{"kategorie": "wörtlich", "text": "\"Du Schastrommel mit mehlverschmiertem Maul!\"  2. Du altes, bösartiges, mehlverschmiertes Lästermaul!  3. Du grindige, alte Giftspritze mit mehlverschmiertem Maul!"}]'::jsonb, ''),
  ('du-moeoeladpappade-schaasroodl', 'Du mööladpappade Schaasroodl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du mehlert-papperte Schasrodel!', '[{"kategorie": "wörtlich", "text": "\"Du Schasrodel mit mehlverschmiertem Maul!\"  2. Du altes, bösartiges, mehlverschmiertes Lästermaul!  3. Du grindige, alte Giftspritze mit mehlverschmiertem Maul!"}]'::jsonb, ''),
  ('dia-haengd-ma-a-a-schnitzl-uman-hois-damit-wenigstns-da-hund-mit-dia-schbueued', 'Dia hängd ma a a Schnitzl uman Hois, damit wenigstns da Hund mit dia schbüüd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dir hängt man ein Schnitzel um den Hals, damit wenigstens der Hund mit dir spielt!', '[{"kategorie": "wörtlich", "text": "\"Man muss dir ein Schnitzel um den Hals hängen, sonst spielt nicht einmal der Hund mehr mit dir!\"  2. Du brauchst ’nen Wurstkranz als Halskette, sonst will dich nicht mal der Dackel sehen!  3. Wenn man dir kein Schnitzel um den Hals bindet, spielt nicht einmal der Nachbarshund mit dir!"}]'::jsonb, ''),
  ('du-bist-a-konifaea-auf-dein-gebiit', 'Du bist a Konifäa auf dein Gebiit!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Du bist eine Konifere auf deinem Gebiet!', '[{"kategorie": "wörtlich", "text": "\"Du bist keine Koryphäe, sondern vielmehr eine Konifere auf deinem Gebiet!\" (scherzhafte Verballhornung von \"Koryphäe\" [=\"Fachgröße\"] zu \"Konifere\" [=Nadelbaum\"])"}, {"kategorie": "", "text": "Du bist völlig unbedarft auf deinem Gebiet - dumm wie ein Baum!  3. Selbst ein Nadelbaum hat mehr Fachwissen als du!"}]'::jsonb, ''),
  ('deine-aung-hosd-a-nua-zum-blaeaedschaun', 'Deine Aung hosd a nua zum Bläädschaun!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Deine Augen hast du auch nur zum Blödschauen!', '[{"kategorie": "wörtlich", "text": "\"Du hast deine Augen wohl nur zum Blödschauen, was?\"  2. Mit deinen Augen machst du auch nix außer Luftgucken, was?  3. Du hast zwei Augen, die blöder schauen als zwei Fenster in ’nen leeren Raum!"}]'::jsonb, ''),
  ('heast-schdeansinga-du-liigsd-in-gaunzn-tog-umanaund-wiara-schdingads-gsoeoechds', 'Heast, Schdeansinga, du liigsd in gaunzn Tog umanaund wiara schdingads Gsööchds!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hey Sternsinger, du liegst den ganzen Tag herum wie ein stinkendes Geselchtes!', '[{"kategorie": "wörtlich", "text": "\"Hey, Sternsinger, du liegst den ganzen Tag herum wie stinkendes Selchfleisch!\"  2. Hör mal her, Traumtänzer, du liegst den ganzen Tag herum wie ein gammelndes Faultier!  3. Hey, du Christkindl, du liegst den ganzen Tag rum wie totes Fleisch!"}]'::jsonb, ''),
  ('waunnd-schdeansinga-kumma-bringan-iare-liada-liachd-und-hoffnung-in-de-dunklen-toog', 'Waunnd Schdeansinga kumma, bringan iare Liada Liachd und Hoffnung in de dunklen Toog!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Wenn die Sternsinger kommen, bringen ihre Lieder Licht und Hoffnung in die dunklen Tage!', '[{"kategorie": "wörtlich", "text": "\"Wenn die Sternsinger Einzug halten, bringen sie mit ihren Liedern Licht und Hoffnung in die dunklen Tage!\"    2. Mit ihren Liedern bringen die Sternsinger Licht ins Dunkel und Wärme in die Herzen!  3. Die Sternsinger bringen mit ihren Liedern einen Schimmer Licht in die dunkle Jahreszeit!"}]'::jsonb, ''),
  ('a-packl-waatschn-is-glei-aufgrissn', 'A Packl Waatschn is glei aufgrissn!', '', '', '', 'Wiener Gaunersprache', 'Ein Packl Watschen ist gleich aufgerissen!', '[{"kategorie": "wörtlich", "text": "\"Gleich gibt''s eine Tracht Prügel!\"  2. Das Watschenpaket ist schon geschnürt!  3. Gleich gibt''s ein Packl Watschen hinter die Ohren!"}]'::jsonb, ''),
  ('draa-di-haam', 'Draa di haam!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Dreh dich heim!', '[{"kategorie": "wörtlich", "text": "\"Geh auf die letzte Reise!\"  2. Verschwinde!  3. [[Vakumm]]! [Verkomme!]  4.[[Hau]] di in Rettich!  5. [[Lass]] dich einpanieren!  6. [[Fäul]] ab!  7. [[Gee]] schdeam!"}]'::jsonb, ''),
  ('kaunnst-leise-gee-daunn-schleich-di', 'Kaunnst leise gee? Daunn schleich di!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Kannst du leise gehen? Dann schleich dich!', '[{"kategorie": "wörtlich", "text": "\"Kannst du leise gehen? Okay, dann mach dich geräuschlos vom Acker!\"  2. Verschwinde – und zwar möglichst geräuschlos und unauffällig!  3. Verzieh dich – möglichst geräuschlos!"}]'::jsonb, 'si schleichn'),
  ('de-rotzn-schbeibm-si-au-waunns-di-seeng', 'De Rotzn schbeibm si au, waunns di seeng!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Die Ratten speiben sich an, wenn sie dich sehen!', '[{"kategorie": "wörtlich", "text": "\"Die Ratten kotzen, wenn sie dich sehen!\"  2. Selbst die Ratten kriegen bei deinem Anblick noch das Kotzen!  3. Bei deinem Anblick kriegen kriegen selbst die Ratten noch Brechreiz!"}]'::jsonb, ''),
  ('des-is-a-luutschbian-dem-hausd-a-waatschn-owe-und-dea-sogt-da-no-danke', 'Des is a Luutschbian - dem hausd a Waatschn owe, und dea sogt da no ''danke''!', '', '', '', 'Wiener Gaunersprache', 'Das ist eine Lutschbirne - dem haust du eine Watsche runter, und der sagt dir noch ''danke''!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Fußabstreifer in Menschengestalt - dem haust du eine Watsche runter, und der sagt dir noch ''danke''!\"  2. Der ist so unterwürfig, der würde sich selber anzeigen, wenn du ihn schlägst!  3. Was für ein Kniefallkandidat - der kriegt eine gescheppert und bedankt sich noch höflich bei dir!"}]'::jsonb, ''),
  ('heit-hoi-i-ma-de-luutschbian-auf-a-blaasal', 'Heit hoi i ma de Luutschbian auf a Blaasal!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Heut'' hol'' ich mir die Lutschbirne auf ein Blaserl!', '[{"kategorie": "wörtlich", "text": "\"Heute hol'' ich mir das Nuckelköpfchen auf einen Blowjob!\"  2. Heute lass ich mir von dem Nuckelköpfchen einen blasen!  3. Heut'' hol'' ich mir den Blasengel zum Oralverkehr!"}]'::jsonb, ''),
  ('de-luutschbian-hod-si-scho-wiida-soeoewa-ausgschbead', 'De Luutschbian hod si scho wiida sööwa ausgschbead!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Diese Lutschbirn hat sich schon wieder selbst ausgesperrt!', '[{"kategorie": "wörtlich", "text": "\"Dieser Nuckelkopf hat sich schon wieder selbst ausgesperrt!\"  2. Der Depp lernt''s nie - er hat sich schon wieder selbst ausgesperrt!  3. Was für ein Dillo - wie oft wird er sich noch selbst aussperren?"}]'::jsonb, ''),
  ('des-is-a-hianbliada-im-endschdadium-den-kaunnst-nimma-behaundln', 'Des is a Hianbliada im Endschdadium - den kaunnst nimma behaundln!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Das ist ein Hirnbluter im Endstadium - den kannst du nicht mehr behandeln!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Hirnbluter, der geistig durch ist - den kannst du nicht mehr behandeln!\"  2. Dem ist nicht mehr zu helfen - er hat sein ganzes Hirn ausgeblutet!  3. Das Hirn von dem ist endgültig ausgeblutet – da hilft nix mehr!"}]'::jsonb, ''),
  ('bei-dia-hod-ned-amoi-de-obtreibung-funktioniad-und-jetzt-bist-zblaeaed-zum-schdeam', 'Bei dia hod ned amoi de Obtreibung funktioniad, und jetzt bist zblääd zum Schdeam!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Bei dir hat nicht einmal die Abtreibung funktioniert - und jetzt bist zu blöd zum Sterben!', '[{"kategorie": "wörtlich", "text": "\"\"Bei dir ist schon die Abtreibung fehlgeschlagen - und jetzt bist zu auch noch zu blöd zum Sterben!\"  2. Bei deiner Zeugung hat jemand den Stecker zu spät gezogen, und jetzt bist du auch noch zu blöd zum Sterben!  3. Du bist so unfassbar dumm - durch Unfall gezeugt und zu blöd zum Sterben!"}]'::jsonb, 'Du bist zblääd zum Schdeam!'),
  ('du-bist-zblaeaed-zum-schdeam', 'Du bist zblääd zum Schdeam!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du bist zu blöd zum Sterben!', '[{"kategorie": "wörtlich", "text": "\"Du bist zu dämlich zum Umfallen!\"  2. Selbst das Sterben wär dir noch zu kompliziert!  3. Bei dir macht selbst der Tod kehrt, weil’s ihm zu blöd ist!"}]'::jsonb, 'Bei dia hod ned amoi de Obtreibung funktioniad, und jetzt bist zblääd zum Schdeam!'),
  ('du-bist-zblaeaed-zum-scheissn', 'Du bist zblääd zum Scheissn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du bist zu blöd zum Scheißen!', '[{"kategorie": "wörtlich", "text": "\"Du bist so dumm, du brauchst ’ne Anleitung fürs Kacken!\"  2. Du bist zu dämlich zum Umfallen!\"  3. Selbst das Scheißen ist dir noch zu kompliziert!"}]'::jsonb, 'Wea zblääd zum Scheissn is, dea hod intellektuell scho bei da Vaduauung sei Endschdation erreichd!'),
  ('wea-zblaeaed-zum-scheissn-is-dea-hod-intellektuell-scho-bei-da-vaduauung-sei-endschdation-erreichd', 'Wea zblääd zum Scheissn is, dea hod intellektuell scho bei da Vaduauung sei Endschdation erreichd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wer zu blöd zum Scheißen ist, der hat intellektuell schon bei der Verdauung die Endstation erreicht!', '[{"kategorie": "wörtlich", "text": "Wer fürs Kacken zu blöd ist, bei dem hört das Denken schon bei der Verdauung auf!  2. Wenn’s Hirn nicht mal für den Stuhlgang reicht, brauchst du auch kein Restprogramm!  3. Sein IQ endet beim Enddarm – weiter geht da nix!"}]'::jsonb, 'Du bist zblääd zum Scheissn!'),
  ('waunnsd-ma-hoefn-wueuesd-kaunnst-mi-scheissn-troong', 'Waunnsd ma höfn wüüsd, kaunnst mi scheissn troong!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn du mir helfen willst, kannst du mich zum Scheißen tragen!', '[{"kategorie": "wörtlich", "text": "\"Wenn du mir helfen willst, kannst du mich aufs Klo tragen!\"  2. \"Willst mir helfen? Dann trag mich doch zum Scheißhaus!\"  3. \"Wenn du mir helfen willst – trag mich, fütter mich, wisch mir den Hintern!\"  4. Ich brauche keine Hilfe - und am allerwenigsten von dir!"}]'::jsonb, ''),
  ('waunn-i-an-oasch-haed-wia-du-a-gsicht-taed-i-min-schleia-scheissn-gee', 'Waunn I an Oasch häd wia du a Gsicht, täd I min Schleia scheissn gee!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn ich einen Arsch hätte wie du ein Gesicht, tät'' ich mit ''nem Schleier scheißen gehen!', '[{"kategorie": "wörtlich", "text": "\"Wenn mein Hintern so aussähe wie dein Gesicht, würde ich mit ''nem Schleier scheißen gehen!\"  2. Wär mein Hintern so entstellt wie dein Gesicht, würde ich mir beim Kacken einen Schleier über den Arsch ziehen!  3. Sähe mein Arsch so aus wie dein Gesicht, würde ich nur nachts scheißen gehen – und selbst da nur mit Schleier!"}]'::jsonb, ''),
  ('waunn-i-an-oasch-haed-wia-du-a-gsicht-daunn-taed-i-mi-ned-amoi-bei-nocht-duach-an-schleia-scheissn-traun', 'Waunn I an Oasch häd wia du a Gsicht, daunn täd I mi ned amoi bei Nocht duach an Schleia scheissn traun!', '', '', '', 'Wiener Gaunersprache', 'Wenn ich einen Arsch hätte wie du ein Gesicht, dann tät'' ich mich nicht einmal bei Nacht durch einen Schleier scheißen trauen!', '[{"kategorie": "wörtlich", "text": "\"Wenn mein Hintern so aussähe wie dein Gesicht, dann würde ich ich mich nicht einmal bei Nacht durch einen Schleier scheißen trauen!\"  2. Wär mein Hintern so entstellt wie dein Gesicht, würde ich es nachts nicht wagen, kacken zu gehen - nicht einmal mit einem Schleier über dem Arsch!  3. Sähe mein Arsch so aus wie dein Gesicht, würde ich es nicht einmal nachts wagen, scheißen zu gehen – selbst wenn ich einen Schleier über dem Hintern hätte!"}]'::jsonb, ''),
  ('wos-schaust-so-deppad-host-kan-feanseea-zhaus', 'Wos schaust so deppad, host kan Feanseea zhaus?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Was schaust du so deppert - hast du keinen Fernseher zu Hause?', '[{"kategorie": "wörtlich", "text": "\"Was glotzt du so blöd - hast du keinen Fernseher zu Hause?\"  2. Was gaffst du so debil - hast du daheim keine Glotze?  3. Was glotzt du so blöd – soll ich tanzen, oder was?"}]'::jsonb, ''),
  ('hoid-de-goschn-du-baunhofsheislbeesn', 'Hoid de Goschn, du Baunhofsheislbeesn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Halt die Goschen, du Bahnhofshäuslbesen!', '[{"kategorie": "wörtlich", "text": "\"Halt die Klappe, du wandelnde Bahnhofsklobürste!\"  2. Halt''s Maul, du rostige Klobürste auf zwei Beinen!  3. Halt die [[Pappen]], du Kotzbrocken!"}]'::jsonb, ''),
  ('host-des-da-kua-ausn-oasch-zoong', 'Host des da Kua ausn Oasch zoong?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hast du das der Kuh aus dem Arsch gezogen?', '[{"kategorie": "wörtlich", "text": "\"Das sieht so zerknittert und verschrumpelt aus, als hättest du es der Kuh aus dem Arsch gezogen!\"  2. Das sieht aus, als wär''s dreimal gekaut, ausgespuckt und plattgesessen worden!  3. Das hat mehr Falten als ein Elefantenhintern!"}]'::jsonb, ''),
  ('heast-du-zoobla-draa-di-oder-i-draa-di', 'Heast, du Zoobla, draa di oder i draa di!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hey, du Zobler, dreh dich oder ich dreh dich!', '[{"kategorie": "wörtlich", "text": "\"Hey, du Trödler, beweg dich oder ich bewege dich!\"  2. Hey, du Lahmarsch – beweg dich oder ich schieb dich an!  3. Hey, du Schnecke, beweg deinen Hintern – sonst tu ich’s!"}]'::jsonb, ''),
  ('waunnst-no-laung-zoowaesd-wiad-da-zug-oone-di-ofoan', 'Waunnst no laung zoowäsd, wiad da Zug oone di ofoan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du noch lange zobelst, wird der Zug ohne dich abfahren!', '[{"kategorie": "wörtlich", "text": "\"Wenn du noch lange zauderst, wird der Zug ohne dich abfahren!\"  2. Wenn du weiter zögerst, fährt der Zug eben ohne dich los!  3. Zaudern bringt dich nicht weiter – also entscheide dich!"}]'::jsonb, ''),
  ('host-a-problem-na-wueuesd-ans', 'Host a Problem? Na? Wüüsd ans?', '', '', '', 'Wiener Gaunersprache', 'Hast du ein Problem? Nein? Willst du eines?', '[{"kategorie": "wörtlich", "text": "\"Gibt’s ein Problem – oder soll ich dir eins machen?\"  2. Hast du ein Problem? Ich bin''s noch nicht – ich bin die letzte Warnung vor deinem Problem!  3. Hast du ein Problem? Wenn nicht, kann ich gern nachhelfen!"}]'::jsonb, ''),
  ('du-kannst-ma-in-buugl-owerutschn-und-mit-da-zungan-bremsn', 'Du kannst ma in Buugl owerutschn und mit da Zungan bremsn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Du kannst mir den Buckel runterrutschen und mit der Zunge bremsen!', '[{"kategorie": "wörtlich", "text": "\"Rutsch mir doch den Rücken lang und bremse unten mit der Zunge!\"  2. Rutsch mir den Regenbogen runter – und küss den Blitz am Ende!  3. Du kannst mich mal kreuzweise!"}]'::jsonb, ''),
  ('babaa-und-schdeig-in-kan-schnaeaehaufn', 'Babaa, und schdeig in kan Schnäähaufn!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Babaa - und steig in keinen Schneehaufen!', '[{"kategorie": "wörtlich", "text": "\"Tschüss - und tritt in keinen Schneehaufen!\"  2. (scherzhaft für): \"Mach’s gut – und stapf nicht aus Versehen in einen Schneehaufen!\"  3. \"Adieu und fall in keinen Schneehaufen!\"  4. \"Ciao, Hals- und Beinbruch!\""}]'::jsonb, ''),
  ('wos-du-reedst-und-wos-a-kua-scheissd-is-dessoewe', 'Wos du reedst und wos a Kua scheissd, is dessöwe!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Was du redest und eine Kuh scheißt, ist dasselbe!', '[{"kategorie": "wörtlich", "text": "\"Wenn du was von dir gibst, kommt dabei dasselbe heraus, wie wenn eine Kuh scheißt!\"  2. Was du von dir gibst, ist geistige Gülle!\"  3. Ein Kuhfladen hat mehr Inhalt als dein Geschwätz!  4. Dein Mundwerk produziert mehr Mist als zehn Kühe!"}]'::jsonb, ''),
  ('a-gsichd-wiara-plottnschbueuela-den-kaunnst-in-gaunzn-tog-aane-aufleeng', 'A Gsichd wiara Plottnschbüüla - den kaunnst in gaunzn Tog aane aufleeng!', '', '', '', 'Wiener Gaunersprache', 'Ein Gesicht wie ein Plattenspieler - dem kannst du den ganzen Tag eine auflegen!', '[{"kategorie": "wörtlich", "text": "\"Der hat ein echtes Watschengesicht - dem könntest du den ganzen Tag eine auflegen!\"  2. Sein Gesicht ist wie ein Boxsack mit Ohren –  dem könntest du den ganzen Tag eine reinhauen!  3. Der hat so ein Prügelprofil – dem könntest du pausenlos eine kleben!"}]'::jsonb, 'wem ane aufleeng'),
  ('hoid-de-goschn-du-haubmtaucha-schdeig-zruck-in-de-senkgruabm-aus-deasd-aussekraeud-bist', 'Hoid de Goschn, du Haubmtaucha - schdeig zruck in de Senkgruabm, aus deasd aussekräud bist!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Halt die Goschen, du Haubentaucher - steig zurück in die Senkgrube, aus der du rausgekrochen bist!', '[{"kategorie": "wörtlich", "text": "\"Halt die Klappe, du Haubentaucher - steig zurück in die Senkgrube, aus der du herausgekrochen bist!\"  2. Halt''s Maul, du Senkgruben-Yeti, und verschwinde dahin, wo du herkamst!  3. Halt den Rand, du Teichungeziefer – und retour ins Loch, aus dem du hervorgekrochen bist!"}]'::jsonb, ''),
  ('mit-seina-feedakroon-is-da-haubmtaucha-da-keenich-vom-teich', 'Mit seina Feedakroon is da Haubmtaucha da Keenich vom Teich!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Mit seiner Federkrone ist der Haubentaucher der König vom Teich!', '[{"kategorie": "wörtlich", "text": "\"Mit der Federkrone auf dem Kopf gibt der Haubentaucher den Teichkönig!\"  2. \"Mit seiner Frisur ist der Haubentaucher eindeutig der Boss vom Weiher!\"  3. \"Der Federschmuck auf seinem Kopf macht den Haubentaucher zum selbsternannten Herrscher des Teichs!\""}]'::jsonb, ''),
  ('de-schnattad-da-in-gaunzn-toog-de-uawaschln-voi-wiara-tuckaantal', 'De schnattad da in gaunzn Toog de Uawaschln voi wiara Tuckaantal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die schnattert dir den ganzen Tag die Ohrwascheln voll wie ein Tuckentchen!', '[{"kategorie": "wörtlich", "text": "\"Die schnattert dir den ganzen Tag die Ohren voll wie eine Tuckente!\" 2. Die gackert dir die Ohren blutig wie ein Blässhuhn!  3. Die schnattert den ganzen Tag wie ein aufgescheuchtes Wasserhuhn!"}]'::jsonb, ''),
  ('des-is-a-gschbritzda-gschdopfda', 'Des is a gschbritzda Gschdopfda!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist ein gespritzer G''stopfter!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein arroganter Schnösel mit Geld!\"  2. Das ist ein typischer neureicher Trottel!  3. Das ist ein hochnäsiger Bonze mit mehr Geld als Grips!"}]'::jsonb, ''),
  ('deppada-huarns-onaniirenda-oaschwixa', 'Deppada huarns-onaniirenda Oaschwixa!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Depperter, hurenonanierender Arschwichser!', '[{"kategorie": "wörtlich", "text": "\"Du vertrottelter, hurenonanierender Arschwichser!\"  2. Du hurenelender, depperter Arschkriecher mit Handbetrieb!  3. Du gehirnbefreites, hurenverficktes Arschloch!"}]'::jsonb, ''),
  ('maunche-maenna-entwickln-si-weida-aundare-bleim-ia-leebm-laung-beidlpracka', 'Maunche Männa entwickln si weida - aundare bleim ia Leebm laung Beidlpracka!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Manche Männer entwickeln sich weiter – andere bleiben ihr Leben lang Beidlpracker!', '[{"kategorie": "wörtlich", "text": "\"Manche werden erwachsen - die anderen bleiben ihr Leben lang Vollpfosten mit Bartwuchs!\"  2. Manche Männer wachsen über sich hinaus – andere bleiben im Selfie-Modus stecken!  3. Die einen werden Männer – die anderen bleiben Maulhelden mit Sackgehänge!"}]'::jsonb, ''),
  ('du-oamsoeoelicha-beidlpracka-dei-anzigs-date-is-dei-rechte-haund', 'Du oamsöölicha Beidlpracka - dei anzigs Date is dei rechte Haund!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Du armseliger Beidlpracker - dein einziges Date ist deine rechte Hand!', '[{"kategorie": "wörtlich", "text": "\"Du armseliger Wichser - dein einziges Date ist deine rechte Hand!\"  2. Du jämmerlicher Flachwichser - der Einzige, der dich regelmäßig anfasst, bist du selbst!  3. Du elender Einhand-Pilot - du wetzt ihn dir ein Leben lang selbst!"}]'::jsonb, ''),
  ('du-oamsoeoelicha-nuudldrucka-dei-anzigs-date-is-dei-rechte-haund', 'Du oamsöölicha Nuudldrucka - dei anzigs Date is dei rechte Haund!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Du armseliger Nudeldrucker - dein einziges Date ist deine rechte Hand!', '[{"kategorie": "wörtlich", "text": "\"Du armseliger Wichser - dein einziges Date ist deine rechte Hand!\"  2. Du jämmerlicher Flachwichser - der Einzige, der dich regelmäßig anfasst, bist du selbst!  3. Du elender Einhand-Pilot - du wetzt ihn dir ein Leben lang selbst!"}]'::jsonb, ''),
  ('du-oamsoeoelicha-haundwaaglfoara-dei-anzigs-date-is-dei-rechte-haund', 'Du oamsöölicha Haundwaaglfoara - dei anzigs Date is dei rechte Haund!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Du armseliger Handwagenfahrer - dein einziges Date ist deine rechte Hand!', '[{"kategorie": "wörtlich", "text": "\"Du armseliger Wichser - dein einziges Date ist deine rechte Hand!\"  2. Du jämmerlicher Flachwichser - der Einzige, der dich regelmäßig anfasst, bist du selbst!  3. Du elender Einhand-Pilot - du wetzt ihn dir ein Leben lang selbst!"}]'::jsonb, ''),
  ('maunche-maenna-entwickln-si-weida-aundare-bleim-ia-leebm-laung-zipflklotscha', 'Maunche Männa entwickln si weida - aundare bleim ia Leebm laung Zipflklotscha!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Manche Männer entwickeln sich weiter – andere bleiben ihr Leben lang Zipfelklatscher!', '[{"kategorie": "wörtlich", "text": "\"Manche werden erwachsen - die anderen bleiben ihr Leben lang Vollpfosten mit Bartwuchs!\"  2. Manche Männer wachsen über sich hinaus – andere bleiben im Selfie-Modus stecken!  3. Die einen werden Männer – die anderen bleiben Maulhelden mit Sackgehänge!"}]'::jsonb, ''),
  ('du-oamsoeoelicha-zipflklotscha-dei-anzigs-dejt-is-dei-rechte-haund', 'Du oamsöölicha Zipflklotscha - dei anzigs Dejt is dei rechte Haund!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Du armseliger Zipfelklatscher - dein einziges Date ist deine rechte Hand!', '[{"kategorie": "wörtlich", "text": "\"Du armseliger Wichser - dein einziges Date ist deine rechte Hand!\"  2. Du jämmerlicher Flachwichser - der Einzige, der dich regelmäßig anfasst, bist du selbst!  3. Du elender Einhand-Pilot - du wetzt ihn dir ein Leben lang selbst!"}]'::jsonb, ''),
  ('dea-fuchtld-min-fliangpracka-umadum-ois-woidada-an-gaunzn-dschungl-daschloong', 'Dea fuchtld min Fliangpracka umadum, ois woidada an gaunzn Dschungl daschloong!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der fuchtelt mit dem Fliegenpracker herum, als wollte er einen ganzen Dschungel damit erschlagen!', '[{"kategorie": "wörtlich", "text": "\"Der schlägt mit der Fliegenklatsche um sich, als wollte er einen ganzen Dschungel damit erschlagen!\"  2. Der wedelt mit dem Fliegenpracker rum, als müsste er Tarzan den Weg freiklopfen!  3. Der schwingt den Fliegenhammer, als wollte er damit ‘ne ganze Elefantenherde vertreiben und nicht bloß ‘ne keine Stubenfliege!"}]'::jsonb, ''),
  ('waunn-da-dea-mit-sein-fliangpracka-ane-tuschd-wochsd-easchd-zwoeoef-schdund-schbaeaeda-wiida-auf', 'Waunn da dea mit sein Fliangpracka ane tuschd, wochsd easchd zwööf Schdund schbääda wiida auf!', '', '', '', 'Wiener Gaunersprache', 'Wenn dir der mit seinem Fliegenpracker eine tuscht, wachst du erst zwölf Stunden später wieder auf!', '[{"kategorie": "wörtlich", "text": "\"Wenn dir der mit seiner Bärenpranke eine verpasst, wachst du erst zwölf Stunden später wieder auf!\"  2. Wenn der dir eine mit seiner Pranke zieht, kriegst du Postkarten aus dem Jenseits!  3. Wenn der dich mit seiner Bärenpranke erwischt, wachst du erst zwölf Stunden später wieder auf – aber mit ‘nem anderen Namen!"}]'::jsonb, ''),
  ('dea-schbueued-auf-sein-fliangpracka-ois-daeda-a-hendl-rupfn', 'Dea schbüüd auf sein Fliangpracka, ois däda a Hendl rupfn!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Der spielt auf seinem Fliegenpracker, als würde er ein Hendl rupfen!', '[{"kategorie": "wörtlich", "text": "\"Der spielt auf seinem Fliegenpracker, als würde er ein Huhn rupfen!\"  2. (scherzhaft für): Der zupft seine Gitarre, als würde er ein Huhn rupfen!  3. Der schrubbt auf den Saiten seiner Gitarre rum, als würde er einem Huhn jede Feder einzeln ausreißen wollen!"}]'::jsonb, ''),
  ('dea-schbueued-auf-sein-pracka-ois-daeda-a-hendl-rupfn', 'Dea schbüüd auf sein Pracka, ois däda a Hendl rupfn!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Der spielt auf seinem Pracker, als würde er ein Hendl rupfen!', '[{"kategorie": "wörtlich", "text": "\"Der spielt auf seinem Pracker, als würde er ein Huhn rupfen!\"  2. (scherzhaft für): Der zupft seine Gitarre, als würde er ein Huhn rupfen!  3. Der schrubbt auf den Saiten seiner Gitarre rum, als würde er einem Huhn jede Feder einzeln ausreißen wollen!"}]'::jsonb, ''),
  ('waunn-mei-muada-in-daeaewichpracka-ghoid-hod-hod-mei-oasch-nochhea-ausgschaud-wia-dea-von-an-rosa-flamingo', 'Waunn mei Muada in Dääwichpracka ghoid hod, hod mei Oasch nochhea ausgschaud wia dea von an rosa Flamingo!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn meine Mutter den Teppichklopfer geholt hat, sah mein Arsch nachher aus wie der von einem rosa Flamingo!', '[{"kategorie": "wörtlich", "text": "\"Wenn meine Mutter den Teppichklopfer gezückt hat, war mein Hintern danach genauso rosa wie bei einem Flamingo!\"  2. Wenn Mama den Teppichklopfer holte, sah mein Hinterteil nachher aus wie ein überreifer [[Paradeiser]]!  3. Wenn die Alte den Klopfer schwang, sah mein Arsch nachher aus wie ein rosa Flamingo!"}]'::jsonb, ''),
  ('mid-an-schnitzlpracka-kaunnst-ned-nua-schnitzl-klopfn-sondan-a-naeaegl-eischlong', 'Mid an Schnitzlpracka kaunnst ned nua Schnitzl klopfn, sondan a Näägl eischlong!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Mit einem Schnitzelpracker kannst du nicht nur Schnitzel klopfen, sondern auch Nägel einschlagen!', '[{"kategorie": "wörtlich", "text": "\"Mit einem Schnitzelhammer kannst du nicht nur Schnitzel klopfen, sondern auch Nägel einschlagen!\"  2. So ein Schnitzelpracker eignet sich nicht nur zum Fleischklopfen – der haut auch locker Nägel in die Wand!  3. Mit dem Fleischklopfer kannst du Schnitzel plattmachen und gleichzeitig dein Wohnzimmer renovieren!"}]'::jsonb, ''),
  ('host-aeae-in-pracka-eigschdeckd-oda-soima-wiida-min-schraufnziaga-umanaundakrotzn', 'Host ää in Pracka eigschdeckd, oda soima wiida min Schraufnziaga umanaundakrotzn?', '', '', '', 'Wiener Gaunersprache', 'Hast du eh den Pracker eingesteckt, oder sollen wir wieder mit’m Schraubenzieher rumkratzen?', '[{"kategorie": "wörtlich", "text": "\"Hast du eh das Brecheisen eingesteckt, oder sollen wir wieder mit dem Schraubenzieher rumkratzen?\"  2. Hast den Pracker dabei oder soll ich wieder mit’m Kinderbesteck rumstochern?  3. Hast du das Eisen eh mit – oder muss ich wieder mit’m Schrauber ran?"}]'::jsonb, ''),
  ('da-neiche-pracka-liigd-supa-in-da-haund-voi-leichd-und-trotzdem-wuchtig', 'Da neiche Pracka liigd supa in da Haund - voi leichd und trotzdem wuchtig!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der neue Pracker liegt super in der Hand – voll leicht und trotzdem wuchtig!', '[{"kategorie": "wörtlich", "text": "\"Der neue Tennisschläger liegt super in der Hand – voll leicht und trotzdem wuchtig!\"  2. Das neue Racket liegt super in der Hand – voll leicht und trotzdem mit viel Punch!  3. Der neue Pracker fühlt sich richtig gut an – kaum Gewicht, aber der haut rein!"}]'::jsonb, ''),
  ('i-hoi-nua-schnoeoe-eadaepfaen-vom-pracka', 'I hoi nua schnöö Eadäpfän vom Pracka!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ich hole nur schnell Erdäpfel vom Pracker!', '[{"kategorie": "", "text": "Ich hole nur rasch Kartoffel vom Gemüsehändler!  2. Ich besorge nur schnell Kartoffeln beim Gemüsehändler!  3. Ich hüpf kurz rüber zum Gemüsestand um ein paar Kartoffeln!"}]'::jsonb, ''),
  ('sii-lauad-scho-auf-mi-min-pracka-in-da-haund', 'Sii lauad scho auf mi min Pracka in da Haund!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sie lauert schon auf mich mit dem Pracker in der Hand!', '[{"kategorie": "", "text": "Sie wartet schon auf mich mit dem Teppichklopfer in der Hand!  2. Sie passt mich ab mit dem Knüppel in der Hand!  3. Ich sehe sie schon vor mir: Teppichklopfer geschultert, Blick tödlich!"}]'::jsonb, ''),
  ('i-prack-de-schnitzln-bis-gaunz-duenn-san', 'I prack de Schnitzln, bis gaunz dünn san!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich pracke die Schnitzel, bis sie ganz dünn sind!', '[{"kategorie": "wörtlich", "text": "\"Ich klopfe die Schnitzel, bis sie ganz dünn sind!\"  2. Ich hau die Schnitzel so lange platt, bis sie fast durchsichtig sind!  3. Ich klopfe das Fleisch weich und dünn – wie es sich für ein Wiener Schnitzel gehört!"}]'::jsonb, ''),
  ('mi-hods-prackd', 'Mi hods prackd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mich hat es geprackt!', '[{"kategorie": "wörtlich", "text": "\"Mich hat''s hingehauen!\"  2. Ich bin auf die Schnauze gefallen!  3. [[Mi hods aufd Pappn ghaud!]]  4. [[I hob a Breezn grissn!]]"}]'::jsonb, ''),
  ('mi-hods-aufprackd', 'Mi hods aufprackd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mich hat es aufgeprackt!', '[{"kategorie": "wörtlich", "text": "\"Mich hat''s aufgehaut!\"  2. Ich bin auf die Schnauze gefallen!  3. [[Mi hods aufd Pappn ghaud!]]  4. [[I hob a Breezn grissn!]]"}]'::jsonb, ''),
  ('mi-hods-hiiprackd', 'Mi hods hiiprackd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mich hat es hingeprackt!', '[{"kategorie": "wörtlich", "text": "\"Mich hat''s hingehauen!\"  2. Ich bin auf die Schnauze gefallen!  3. [[Mi hods aufd Pappn ghaud!]]  4. [[I hob a Breezn grissn!]]"}]'::jsonb, 'Mi hods aufd Pappn ghaud!'),
  ('mi-hods-aufd-pappn-ghaud', 'Mi hods aufd Pappn ghaud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mich hat es auf die Pappen gehauen!', '[{"kategorie": "wörtlich", "text": "\"Ich bin auf die Schnauze gefallen!\"  2. Ich bin voll auf die Fresse gefallen!  3. [[Mi hods hiiprackd!]]  4. [[I hob a Breezn grissn!]]"}]'::jsonb, 'Mi hods prackd!'),
  ('i-hob-a-breezn-grissn', 'I hob a Breezn grissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich habe eine Brezen gerissen!', '[{"kategorie": "wörtlich", "text": "\"Mich hat''s hingehauen!\"  2. Ich bin auf die Schnauze gefallen!  3. [[Mi hods aufd Pappn ghaud!]]"}]'::jsonb, 'Mi hods prackd!'),
  ('pracka-kriang', 'Pracka kriang', '', '', '', 'Wiener Sprüche, die sitzen!', 'Pracker kriegen', '[{"kategorie": "wörtlich", "text": "\"Schläge bekommen\""}, {"kategorie": "", "text": "eine Tracht Prügel abkassieren"}, {"kategorie": "", "text": "[[Plesch]] kriang"}, {"kategorie": "", "text": "[[Kräcka]] kriang"}]'::jsonb, 'Ois Kinda hauma Pracka kriagd, wiama min Papa sein Rasiira in Haumsta a Glotzn gschniidn haum!'),
  ('ois-kinda-hauma-pracka-kriagd-wiama-min-papa-sein-rasiira-in-haumsta-a-glotzn-gschniidn-haum', 'Ois Kinda hauma Pracka kriagd, wiama min Papa sein Rasiira in Haumsta a Glotzn gschniidn haum!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Als Kinder haben wir Pracker gekriegt, wie wir mit Papas Rasierer dem Hamster eine Glatze geschnitten haben!', '[{"kategorie": "wörtlich", "text": "\"Als Kinder haben wir ordentlich Prügel bezogen, nachdem wir mit Papas Rasierer dem Hamster eine Glatze geschnitten hatten!\"  2. Als Kinder haben wir mächtig was auf den Deckel bekommen, nachdem wir mit Papas Rasierer dem Hamster eine Glatze verpasst hatten!  3. Als Kinder haben wir richtig einen draufgekriegt, weil wir dem Hamster mit Papas Rasierer den Irokesen verpasst hatten!"}]'::jsonb, 'Pracka kriang'),
  ('kraecka-kriang', 'Kräcka kriang', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Kräcker kriegen', '[{"kategorie": "wörtlich", "text": "\"Schläge bekommen\""}, {"kategorie": "", "text": "eine Tracht Prügel abkassieren"}, {"kategorie": "", "text": "[[Plesch]] kriang"}, {"kategorie": "", "text": "[[Pracka]] kriang"}]'::jsonb, ''),
  ('dea-oasch-hod-uns-einelossn-owa-dafia-hoda-jetzd-kraecka-kriagd-dass-eam-de-uan-pfeifn', 'Dea Oasch hod uns einelossn - owa dafia hoda jetzd Kräcka kriagd, dass eam de Uan pfeifn!', '', '', '', 'Wiener Gaunersprache', 'Der Arsch hat uns reingelassen - aber dafür hat er jetzt Kräcker gekriegt, dass ihm die Ohren pfeifen!', '[{"kategorie": "wörtlich", "text": "\"Der Saukerl hat uns reingelegt - aber dafür hat er jetzt Kräcker gekriegt, dass ihm die Ohren pfeifen!\"  2. Der Hund hat uns hintergangen – aber dafür hat er jetzt ordentlich Kräcker kassiert!  3. Der Bastard hat uns sauber über den Tisch gezogen – aber dafür gab’s dann Kräcker. Mit Nachhall!"}]'::jsonb, ''),
