  ('plesch-kriang', 'Plesch kriang', '', '', '', 'Wiener Sprüche, die sitzen!', 'Plesch kriegen', '[{"kategorie": "wörtlich", "text": "\"Schläge bekommen\""}, {"kategorie": "", "text": "eine Tracht Prügel abkassieren"}, {"kategorie": "", "text": "[[Pracka]] kriang"}, {"kategorie": "", "text": "[[Kräcka]] kriang"}]'::jsonb, ''),
  ('de-plesch-host-kriagd-waeusd-uns-vapfiffn-host-du-oasch', 'De Plesch host kriagd, wäusd uns vapfiffn host, du Oasch!', '', '', '', 'Wiener Gaunersprache', 'Die Plesch hast gekriegt, weil du uns verpfiffen hast, du Arsch!', '[{"kategorie": "wörtlich", "text": "\"Die Prügel hast du kassiert, weil du uns verpfiffen hast, du Arsch!\"  2. Die Schellen hast du dir eingehandelt, weil du uns angeschwärzt hast, du mieser Hund!  3. Die Tracht Prügel hast du dir redlich verdient – wer uns verpfeift, kriegt halt was aufs Maul!"}]'::jsonb, 'Plesch kriang'),
